{
  "name": "Opa Suite Dashboard",
  "description": "A professional service dashboard for Opa Suite, featuring real-time status monitoring, waiting lists, and attendant tracking with an admin configuration panel."
}

export type TicketStatus = 'waiting' | 'in_service' | 'finished';

export interface Ticket {
  id: string;
  protocol: string;
  clientName: string;
  contact: string;
  waitTimeSeconds: number; // Time waiting in queue
  durationSeconds?: number; // Time in service
  status: TicketStatus;
  attendantName?: string;
  department?: string;
}

export interface Attendant {
  id: string;
  name: string;
  status: 'online' | 'offline' | 'busy';
  activeChats: number;
}

export interface DashboardStats {
  waitingCount: number;
  inServiceCount: number;
  attendantCount: number;
  avgWaitTimeSeconds: number;
}

export interface AppConfig {
  apiUrl: string;
  apiToken: string;
}

import { Ticket, Attendant, AppConfig } from '../types';

// Mock Data Generators
const NAMES = ['Maria Silva', 'João Souza', 'Ana Pereira', 'Carlos Oliveira', 'Fernanda Lima', 'Roberto Santos'];
const CONTACTS = ['maria@exemplo.com', '11999998888', 'ana.p@company.com', 'carlos@tech.br', 'fernanda@design.com', '11988887777'];
const ATTENDANTS = ['Pedro Suporte', 'Julia Atendimento', 'Marcos Vendas', 'Lucia Financeiro', 'Rafael N2'];

function generateMockTickets(): Ticket[] {
  const tickets: Ticket[] = [];

  // Generate Waiting Tickets
  for (let i = 0; i < 10; i++) {
    tickets.push({
      id: `WAIT-${i}`,
      protocol: `202405${1000 + i}`,
      clientName: NAMES[i % NAMES.length],
      contact: CONTACTS[i % CONTACTS.length],
      waitTimeSeconds: Math.floor(Math.random() * 600) + 60, // 1 to 10 mins
      status: 'waiting',
      department: 'Suporte Geral'
    });
  }

  // Generate In Service Tickets
  for (let i = 0; i < 23; i++) {
    tickets.push({
      id: `SERV-${i}`,
      protocol: `202405${2000 + i}`,
      clientName: NAMES[(i + 2) % NAMES.length],
      contact: CONTACTS[(i + 2) % CONTACTS.length],
      waitTimeSeconds: 120,
      durationSeconds: Math.floor(Math.random() * 1800) + 300, // 5 to 30 mins
      status: 'in_service',
      attendantName: ATTENDANTS[i % ATTENDANTS.length],
      department: 'Vendas'
    });
  }

  return tickets;
}

function generateMockAttendants(): Attendant[] {
  return ATTENDANTS.map((name, idx) => ({
    id: `ATT-${idx}`,
    name,
    status: Math.random() > 0.2 ? 'online' : 'busy',
    activeChats: Math.floor(Math.random() * 5)
  }));
}

// API Service
export const opaService = {
  fetchData: async (config: AppConfig): Promise<{ tickets: Ticket[], attendants: Attendant[] }> => {
    // NOTE: In a real production environment, this would perform a fetch request.
    // Due to CORS restrictions in this demo environment and lack of a real backend proxy, 
    // we simulate the API call latency and structure.

    // If we had a real proxy, the code would look like this:
    /*
    if (config.apiUrl && config.apiToken) {
      try {
        const response = await fetch(`${config.apiUrl}/dashboards/monitor`, {
          headers: { 'Authorization': `Bearer ${config.apiToken}` }
        });
        if (!response.ok) throw new Error('Failed to fetch');
        return await response.json();
      } catch (e) {
        console.error("API Error", e);
        // Fallback to mock
      }
    }
    */

    return new Promise((resolve) => {
      setTimeout(() => {
        resolve({
          tickets: generateMockTickets(),
          attendants: generateMockAttendants()
        });
      }, 800); // Simulate network latency
    });
  }
};

