import React from 'react';
import { Ticket } from '../types';
import { Clock, User, Mail, Hash, Phone } from 'lucide-react';

interface TicketListProps {
  title: string;
  tickets: Ticket[];
  type: 'waiting' | 'in_service';
}

const formatTime = (seconds: number) => {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
};

export const TicketList: React.FC<TicketListProps> = ({ title, tickets, type }) => {
  const isWaiting = type === 'waiting';
  const accentColor = isWaiting ? 'border-amber-500' : 'border-sky-500';
  const badgeColor = isWaiting ? 'bg-amber-500/10 text-amber-500' : 'bg-sky-500/10 text-sky-500';

  return (
    <div className="bg-slate-800 border border-slate-700 rounded-xl overflow-hidden flex flex-col h-full shadow-lg">
      <div className={`p-4 border-b border-slate-700 bg-slate-800/50 flex justify-between items-center border-l-4 ${accentColor}`}>
        <h3 className="font-semibold text-lg text-white uppercase tracking-wide flex items-center gap-2">
          {isWaiting ? <Clock className="w-5 h-5 text-amber-500" /> : <User className="w-5 h-5 text-sky-500" />}
          {title}
        </h3>
        <span className={`px-2 py-1 rounded text-xs font-bold ${badgeColor}`}>
          {tickets.length} Total
        </span>
      </div>

      <div className="overflow-x-auto flex-1">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-900/50 text-slate-400 text-xs uppercase tracking-wider">
              <th className="p-4 font-medium">Cliente</th>
              <th className="p-4 font-medium">Contato</th>
              <th className="p-4 font-medium text-right">{isWaiting ? 'Espera' : 'Duração'}</th>
              <th className="p-4 font-medium text-right">Protocolo</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-700/50">
            {tickets.map((ticket) => (
              <tr key={ticket.id} className="hover:bg-slate-700/30 transition-colors group">
                <td className="p-4">
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold ${isWaiting ? 'bg-amber-900/50 text-amber-400' : 'bg-sky-900/50 text-sky-400'}`}>
                      {ticket.clientName.substring(0, 2).toUpperCase()}
                    </div>
                    <div>
                      <p className="font-medium text-slate-200">{ticket.clientName}</p>
                      {ticket.attendantName && (
                        <p className="text-xs text-slate-500">Atendente: {ticket.attendantName}</p>
                      )}
                    </div>
                  </div>
                </td>
                <td className="p-4 text-slate-400 text-sm">
                   <div className="flex items-center gap-2">
                      {ticket.contact.includes('@') ? <Mail className="w-3 h-3"/> : <Phone className="w-3 h-3"/>}
                      {ticket.contact}
                   </div>
                </td>
                <td className="p-4 text-right">
                  <span className={`font-mono text-sm font-medium ${isWaiting ? 'text-amber-400' : 'text-slate-300'}`}>
                    {formatTime(isWaiting ? ticket.waitTimeSeconds : (ticket.durationSeconds || 0))}
                  </span>
                </td>
                <td className="p-4 text-right">
                   <div className="flex items-center justify-end gap-1 text-slate-500 font-mono text-sm group-hover:text-slate-300">
                      <Hash className="w-3 h-3" />
                      {ticket.protocol}
                   </div>
                </td>
              </tr>
            ))}
            {tickets.length === 0 && (
              <tr>
                <td colSpan={4} className="p-8 text-center text-slate-500 italic">
                  Nenhum atendimento neste status.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Save, Server, Key, Info } from 'lucide-react';
import { AppConfig } from '../types';

interface SettingsProps {
  config: AppConfig;
  onSave: (config: AppConfig) => void;
}

export const Settings: React.FC<SettingsProps> = ({ config, onSave }) => {
  const [url, setUrl] = useState(config.apiUrl);
  const [token, setToken] = useState(config.apiToken);
  const [saved, setSaved] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ apiUrl: url, apiToken: token });
    setSaved(true);
    setTimeout(() => setSaved(false), 3000);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      <div>
        <h2 className="text-2xl font-bold text-white mb-2">Configurações de Conexão</h2>
        <p className="text-slate-400">Configure a conexão com a API do Opa Suite para alimentar o dashboard.</p>
      </div>

      <form onSubmit={handleSubmit} className="bg-slate-800 border border-slate-700 rounded-xl p-8 shadow-xl">
        <div className="space-y-6">

          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2 flex items-center gap-2">
              <Server className="w-4 h-4 text-sky-500" />
              URL do Provedor (API)
            </label>
            <div className="relative">
                <input
                  type="url"
                  value={url}
                  onChange={(e) => setUrl(e.target.value)}
                  placeholder="https://api.opasuite.com.br"
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white placeholder-slate-600 focus:outline-none focus:ring-2 focus:ring-sky-500 transition-all"
                />
            </div>
            <p className="text-xs text-slate-500 mt-2">A URL base da sua instância ou da API oficial.</p>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2 flex items-center gap-2">
              <Key className="w-4 h-4 text-amber-500" />
              Token de Autenticação
            </label>
            <input
              type="password"
              value={token}
              onChange={(e) => setToken(e.target.value)}
              placeholder="Ex: eyJ0eXAiOiJKV1QiLCJhbGci..."
              className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white placeholder-slate-600 focus:outline-none focus:ring-2 focus:ring-sky-500 transition-all"
            />
             <p className="text-xs text-slate-500 mt-2">Token Bearer gerado no painel administrativo do Opa Suite.</p>
          </div>

          <div className="bg-sky-900/20 border border-sky-900/50 rounded-lg p-4 flex gap-3">
             <Info className="w-5 h-5 text-sky-400 flex-shrink-0 mt-0.5" />
             <div className="text-sm text-sky-200/80">
                <p className="font-semibold text-sky-400 mb-1">Como obter as credenciais:</p>
                <ol className="list-decimal pl-4 space-y-1">
                    <li>Acesse seu painel Opa Suite.</li>
                    <li>Vá em Configurações &gt; Integrações &gt; API.</li>
                    <li>Gere um novo token e copie os dados.</li>
                </ol>
             </div>
          </div>

        </div>

        <div className="mt-8 flex justify-end">
          <button
            type="submit"
            className="flex items-center gap-2 bg-sky-600 hover:bg-sky-500 text-white px-6 py-3 rounded-lg font-medium transition-all transform hover:scale-105 active:scale-95 shadow-lg shadow-sky-900/50"
          >
            <Save className="w-5 h-5" />
            {saved ? 'Salvo com Sucesso!' : 'Salvar Configurações'}
          </button>
        </div>
      </form>
    </div>
  );
};

import React, { useMemo } from 'react';
import { Ticket, Attendant } from '../types';
import { StatCard } from './StatCard';
import { TicketList } from './TicketList';
import { Clock, Users, Headset, Timer } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DashboardProps {
  tickets: Ticket[];
  attendants: Attendant[];
}

const formatTime = (seconds: number) => {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
};

export const Dashboard: React.FC<DashboardProps> = ({ tickets, attendants }) => {

  const stats = useMemo(() => {
    const waiting = tickets.filter(t => t.status === 'waiting');
    const inService = tickets.filter(t => t.status === 'in_service');

    const totalWaitTime = waiting.reduce((acc, curr) => acc + curr.waitTimeSeconds, 0);
    const avgWait = waiting.length > 0 ? totalWaitTime / waiting.length : 0;

    return {
      waitingCount: waiting.length,
      inServiceCount: inService.length,
      attendantCount: attendants.length,
      onlineAttendants: attendants.filter(a => a.status === 'online').length,
      avgWaitTimeSeconds: Math.round(avgWait),
      waitingList: waiting.sort((a, b) => b.waitTimeSeconds - a.waitTimeSeconds), // Longest wait first
      inServiceList: inService.sort((a, b) => (b.durationSeconds || 0) - (a.durationSeconds || 0)),
    };
  }, [tickets, attendants]);

  // Data for the chart
  const chartData = [
    { name: 'Em Espera', value: stats.waitingCount, color: '#f59e0b' },
    { name: 'Atendimento', value: stats.inServiceCount, color: '#0ea5e9' },
    { name: 'Atendentes', value: stats.attendantCount, color: '#10b981' },
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-500">

      {/* Top Header - Average Time */}
      <div className="bg-gradient-to-r from-slate-800 to-slate-900 border border-slate-700 rounded-xl p-6 flex flex-col md:flex-row items-center justify-between shadow-xl">
        <div>
          <h2 className="text-xl font-bold text-white flex items-center gap-2">
            <Timer className="w-6 h-6 text-sky-400" />
            Status de Atendimento
          </h2>
          <p className="text-slate-400 text-sm mt-1">Monitoramento em tempo real da operação.</p>
        </div>
        <div className="mt-4 md:mt-0 flex items-center gap-4 bg-slate-950/50 px-6 py-3 rounded-lg border border-slate-800">
          <span className="text-slate-400 font-medium uppercase text-sm tracking-wide">Tempo Médio de Espera</span>
          <span className={`text-2xl font-mono font-bold ${stats.avgWaitTimeSeconds > 600 ? 'text-red-500' : 'text-emerald-400'}`}>
            {formatTime(stats.avgWaitTimeSeconds)}
          </span>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <StatCard
          title="Em Espera"
          value={stats.waitingCount}
          icon={<Clock className="text-amber-500" />}
          colorClass="text-amber-500"
          trend="Clientes aguardando"
        />
        <StatCard
          title="Em Atendimento"
          value={stats.inServiceCount}
          icon={<Headset className="text-sky-500" />}
          colorClass="text-sky-500"
          trend="Conversas ativas"
        />
        <StatCard
          title="Atendentes"
          value={stats.attendantCount}
          icon={<Users className="text-emerald-500" />}
          colorClass="text-emerald-500"
          trend={`${stats.onlineAttendants} Online agora`}
        />
      </div>

      {/* Content Columns */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6 h-[800px] xl:h-[600px]">
        {/* Waiting List */}
        <div className="h-full">
           <TicketList 
             title="Em Espera" 
             tickets={stats.waitingList} 
             type="waiting" 
           />
        </div>

        {/* In Service List */}
        <div className="h-full flex flex-col gap-6">
           <div className="flex-1">
             <TicketList 
               title="Em Atendimento" 
               tickets={stats.inServiceList} 
               type="in_service" 
             />
           </div>

           {/* Mini Chart Section for visual flair */}
           <div className="h-48 bg-slate-800 border border-slate-700 rounded-xl p-4 hidden xl:block">
              <p className="text-xs uppercase text-slate-500 font-bold mb-2 tracking-wider">Distribuição de Volume</p>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData} layout="vertical" margin={{ left: 0, right: 20 }}>
                  <XAxis type="number" hide />
                  <YAxis dataKey="name" type="category" width={100} tick={{ fill: '#94a3b8', fontSize: 12 }} axisLine={false} tickLine={false} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '8px' }}
                    cursor={{fill: '#334155', opacity: 0.2}}
                  />
                  <Bar dataKey="value" barSize={20} radius={[0, 4, 4, 0]}>
                    {chartData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Settings } from './components/Settings';
import { opaService } from './services/opaService';
import { Ticket, Attendant, AppConfig } from './types';

// Initial config (could be loaded from localStorage in a real app)
const INITIAL_CONFIG: AppConfig = {
  apiUrl: '',
  apiToken: ''
};

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'dashboard' | 'settings'>('dashboard');
  const [config, setConfig] = useState<AppConfig>(INITIAL_CONFIG);
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [attendants, setAttendants] = useState<Attendant[]>([]);
  const [loading, setLoading] = useState(false);
  const [lastUpdate, setLastUpdate] = useState<Date>(new Date());

  // Data fetching logic
  const refreshData = useCallback(async () => {
    // Only show loading on initial fetch or settings change, not polling
    if (tickets.length === 0) setLoading(true);

    try {
      const data = await opaService.fetchData(config);
      setTickets(data.tickets);
      setAttendants(data.attendants);
      setLastUpdate(new Date());
    } catch (error) {
      console.error("Failed to fetch dashboard data", error);
    } finally {
      setLoading(false);
    }
  }, [config, tickets.length]);

  // Initial fetch and polling interval
  useEffect(() => {
    refreshData();
    const intervalId = setInterval(refreshData, 30000); // Update every 30 seconds
    return () => clearInterval(intervalId);
  }, [refreshData]);

  const handleSaveConfig = (newConfig: AppConfig) => {
    setConfig(newConfig);
    // In a real app, save to localStorage here
    refreshData(); // Force refresh with new creds
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-sky-500/30">

      {/* Mobile Overlay Background */}
      <div className="fixed inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none z-0"></div>

      <Sidebar currentView={currentView} onChangeView={setCurrentView} />

      <main className="md:pl-64 transition-all duration-300 relative z-10">
        <header className="h-16 border-b border-slate-800 bg-slate-900/80 backdrop-blur-md sticky top-0 z-40 px-6 flex items-center justify-between">
          <h1 className="text-xl font-bold text-white capitalize">
            {currentView === 'dashboard' ? 'Monitoramento' : 'Painel Administrativo'}
          </h1>
          <div className="flex items-center gap-3">
             {loading && <span className="flex h-2 w-2 rounded-full bg-sky-500 animate-pulse"></span>}
             <span className="text-xs text-slate-500 font-mono hidden sm:block">
               Atualizado: {lastUpdate.toLocaleTimeString()}
             </span>
          </div>
        </header>

        <div className="p-6 max-w-[1920px] mx-auto">
          {loading && tickets.length === 0 ? (
            <div className="flex items-center justify-center h-[60vh]">
              <div className="flex flex-col items-center gap-4">
                 <div className="w-12 h-12 border-4 border-sky-500/30 border-t-sky-500 rounded-full animate-spin"></div>
                 <p className="text-slate-500 animate-pulse">Carregando dados...</p>
              </div>
            </div>
          ) : (
            <>
              {currentView === 'dashboard' && (
                <Dashboard tickets={tickets} attendants={attendants} />
              )}
              {currentView === 'settings' && (
                <Settings config={config} onSave={handleSaveConfig} />
              )}
            </>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

