import React from 'react';

interface StatCardProps {
  title: string;
  value: number | string;
  icon: React.ReactNode;
  colorClass: string;
  trend?: string;
}

export const StatCard: React.FC<StatCardProps> = ({ title, value, icon, colorClass, trend }) => {
  return (
    <div className="bg-slate-800 border border-slate-700 rounded-xl p-6 flex items-start justify-between hover:border-slate-600 transition-all shadow-lg relative overflow-hidden group">
      <div className={`absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity transform group-hover:scale-110 duration-500 ${colorClass}`}>
        {React.isValidElement(icon) && React.cloneElement(icon as React.ReactElement<any>, { size: 64 })}
      </div>

      <div className="z-10">
        <p className="text-slate-400 text-sm font-medium uppercase tracking-wider mb-1">{title}</p>
        <h3 className="text-3xl font-bold text-white">{value}</h3>
        {trend && (
          <p className="text-xs text-slate-500 mt-2 flex items-center gap-1">
             {trend}
          </p>
        )}
      </div>

      <div className={`p-3 rounded-lg bg-slate-900/50 ${colorClass} text-white z-10`}>
        {icon}
      </div>
    </div>
  );
};

import { Ticket, Attendant, AppConfig, TicketStatus } from '../types';

// Mock Data Generators
const NAMES = ['Maria Silva', 'João Souza', 'Ana Pereira', 'Carlos Oliveira', 'Fernanda Lima', 'Roberto Santos'];
const CONTACTS = ['maria@exemplo.com', '11999998888', 'ana.p@company.com', 'carlos@tech.br', 'fernanda@design.com', '11988887777'];
const ATTENDANTS = ['Pedro Suporte', 'Julia Atendimento', 'Marcos Vendas', 'Lucia Financeiro', 'Rafael N2'];

function generateMockTickets(): Ticket[] {
  const tickets: Ticket[] = [];

  // Generate Waiting Tickets
  for (let i = 0; i < 10; i++) {
    tickets.push({
      id: `WAIT-${i}`,
      protocol: `202405${1000 + i}`,
      clientName: NAMES[i % NAMES.length],
      contact: CONTACTS[i % CONTACTS.length],
      waitTimeSeconds: Math.floor(Math.random() * 600) + 60, // 1 to 10 mins
      status: 'waiting',
      department: 'Suporte Geral'
    });
  }

  // Generate In Service Tickets
  for (let i = 0; i < 23; i++) {
    tickets.push({
      id: `SERV-${i}`,
      protocol: `202405${2000 + i}`,
      clientName: NAMES[(i + 2) % NAMES.length],
      contact: CONTACTS[(i + 2) % CONTACTS.length],
      waitTimeSeconds: 120,
      durationSeconds: Math.floor(Math.random() * 1800) + 300, // 5 to 30 mins
      status: 'in_service',
      attendantName: ATTENDANTS[i % ATTENDANTS.length],
      department: 'Vendas'
    });
  }

  return tickets;
}

function generateMockAttendants(): Attendant[] {
  return ATTENDANTS.map((name, idx) => ({
    id: `ATT-${idx}`,
    name,
    status: Math.random() > 0.2 ? 'online' : 'busy',
    activeChats: Math.floor(Math.random() * 5)
  }));
}

// Helper to calculate seconds from a date string
function calculateSeconds(dateStr?: string): number {
  if (!dateStr) return 0;
  const start = new Date(dateStr).getTime();
  const now = new Date().getTime();
  return Math.max(0, Math.floor((now - start) / 1000));
}

// Helper to map API status string to internal TicketStatus
function mapApiStatus(status?: string): TicketStatus {
  if (!status) return 'waiting';
  const s = status.toLowerCase();
  // Adjust these keywords based on your specific API response values
  if (s.includes('wait') || s.includes('pend') || s.includes('open') || s.includes('fila')) return 'waiting';
  if (s.includes('attend') || s.includes('service') || s.includes('chat') || s.includes('progress')) return 'in_service';
  return 'finished';
}

// API Service
export const opaService = {
  fetchData: async (config: AppConfig): Promise<{ tickets: Ticket[], attendants: Attendant[] }> => {
    // 1. Try Real API if config exists
    if (config.apiUrl && config.apiToken) {
      try {
        const baseUrl = config.apiUrl.replace(/\/$/, '');
        const headers = { 
          'Authorization': `Bearer ${config.apiToken}`,
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        };

        console.log(`[OpaService] Attempting to fetch from ${baseUrl}...`);

        // We try standard REST endpoints. 
        // NOTE: You might need to adjust '/api/v1/tickets' to matches your exact Opa Suite version (e.g. /dashboards/monitor)
        const [ticketsResponse, agentsResponse] = await Promise.allSettled([
          fetch(`${baseUrl}/api/v1/tickets?status=open,pending,in_progress`, { headers }),
          fetch(`${baseUrl}/api/v1/agents`, { headers })
        ]);

        let tickets: Ticket[] = [];
        let attendants: Attendant[] = [];

        // Process Tickets
        if (ticketsResponse.status === 'fulfilled' && ticketsResponse.value.ok) {
          const data = await ticketsResponse.value.json();
          const list = Array.isArray(data) ? data : (data.data || []); // Handle { data: [...] } or [...]

          tickets = list.map((t: any) => ({
            id: String(t.id || t._id),
            protocol: t.protocol || `PROT-${t.id}`,
            clientName: t.contact?.name || t.client_name || 'Cliente Desconhecido',
            contact: t.contact?.email || t.contact?.phone || t.contact || 'N/A',
            waitTimeSeconds: calculateSeconds(t.created_at || t.started_at),
            durationSeconds: t.accepted_at ? calculateSeconds(t.accepted_at) : undefined,
            status: mapApiStatus(t.status),
            attendantName: t.agent?.name || t.attendant_name,
            department: t.department?.name || t.department
          }));
        } else {
           if (ticketsResponse.status === 'fulfilled') {
             console.warn('[OpaService] Tickets fetch failed:', ticketsResponse.value.status, ticketsResponse.value.statusText);
           }
        }

        // Process Agents
        if (agentsResponse.status === 'fulfilled' && agentsResponse.value.ok) {
          const data = await agentsResponse.value.json();
          const list = Array.isArray(data) ? data : (data.data || []);

          attendants = list.map((a: any) => ({
            id: String(a.id),
            name: a.name || 'Agente',
            status: a.status === 'online' || a.is_online ? 'online' : 'busy', // Simplification
            activeChats: a.active_chats || 0
          }));
        }

        // If we got valid data, return it. Otherwise throw to trigger fallback.
        if (tickets.length > 0 || attendants.length > 0) {
          console.log(`[OpaService] Success. Loaded ${tickets.length} tickets and ${attendants.length} attendants.`);
          return { tickets, attendants };
        } else {
          throw new Error("No data returned from API or API unreachable");
        }

      } catch (error) {
        console.error("[OpaService] Connection failed or invalid response. Falling back to Mock Data.", error);
        // We intentionally fall through to the mock data return below so the UI doesn't crash.
      }
    }

    // 2. Mock Data Fallback
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve({
          tickets: generateMockTickets(),
          attendants: generateMockAttendants()
        });
      }, 800); 
    });
  }
};

