        }

        // Process Agents
        if (agentsResult.status === 'fulfilled') {
          const response = agentsResult.value;
          if (response.ok) {
            isSuccess = true; // Mark as success if at least agents loaded
            try {
              const data = await response.json();
              const list = Array.isArray(data) ? data : (data.data || data.items || []);

              console.log(`[OpaService] Agents raw count: ${list.length}`);

              attendants = list.map((a: any) => ({
                id: String(a.id || a._id),
                name: a.name || 'Agente',
                status: (a.status === 'online' || a.is_online) ? 'online' : 'busy',
                activeChats: a.active_chats || a.chats_count || 0
              }));
            } catch (jsonError) {
               console.error('[OpaService] Error parsing agents JSON:', jsonError);
            }
          } else {
            console.warn(`[OpaService] Agents endpoint returned status: ${response.status} ${response.statusText}`);
          }
        } else {
           console.error('[OpaService] Agents fetch network error:', agentsResult.reason);
        }

        // IMPORTANT: If we successfully connected (HTTP 200) to at least one endpoint, 
        // we return the data, even if empty. We do NOT fallback to mock data just because arrays are empty.
        if (isSuccess) {
          console.log(`[OpaService] Successfully loaded real data. Tickets: ${tickets.length}, Agents: ${attendants.length}`);
          return { tickets, attendants };
        } else {
          throw new Error("API requests failed (404/401/500 or Network Error). Checking console for details.");
        }

      } catch (error) {
        console.error("[OpaService] Connection failed. Fallback to Mock Data activated.", error);
        // Fallback to mock data allows the UI to remain functional if API is down/wrong
      }
    }

    // 2. Mock Data Fallback
    // Only reached if config is missing OR if the try-catch block caught an error
    return new Promise((resolve) => {
      // Small delay to simulate network if falling back
      setTimeout(() => {
        resolve({
          tickets: generateMockTickets(),
          attendants: generateMockAttendants()
        });
      }, 800); 
    });
  }
};

