  // Generate In Service Tickets
  for (let i = 0; i < 23; i++) {
    tickets.push({
      id: `SERV-${i}`,
      protocol: `202405${2000 + i}`,
      clientName: NAMES[(i + 2) % NAMES.length],
      contact: CONTACTS[(i + 2) % CONTACTS.length],
      waitTimeSeconds: 120,
      durationSeconds: Math.floor(Math.random() * 1800) + 300, // 5 to 30 mins
      status: 'in_service',
      attendantName: ATTENDANTS[i % ATTENDANTS.length],
      department: 'Vendas'
    });
  }

  return tickets;
}

function generateMockAttendants(): Attendant[] {
  return ATTENDANTS.map((name, idx) => ({
    id: `ATT-${idx}`,
    name,
    status: Math.random() > 0.2 ? 'online' : 'busy',
    activeChats: Math.floor(Math.random() * 5)
  }));
}

// Helper to calculate seconds from a date string
function calculateSeconds(dateStr?: string): number {
  if (!dateStr) return 0;
  const start = new Date(dateStr).getTime();
  const now = new Date().getTime();
  return Math.max(0, Math.floor((now - start) / 1000));
}

// Helper to map API status string to internal TicketStatus
function mapApiStatus(status?: string): TicketStatus {
  if (!status) return 'waiting';
  const s = status.toUpperCase();
  // Opa Suite: EA = Em Atendimento, A = Aberto (Fila)
  if (s === 'EA' || s === 'ATENDIMENTO' || s.includes('SERVICE')) return 'in_service';
  if (s === 'F' || s === 'FINALIZADO' || s === 'R' || s === 'RESOLVIDO') return 'finished';
  return 'waiting';
}

// API Service
export const opaService = {
  fetchData: async (config: AppConfig): Promise<{ tickets: Ticket[], attendants: Attendant[] }> => {
    // 1. Try to fetch from our Local Proxy (Server.js)
    // We ignore the passed 'config' for the fetch URL because server.js reads it securely from DB.
    // However, we check if config exists in App state to know if we SHOULD attempt fetch.
    if (config.apiUrl && config.apiToken) {
      try {
        console.log(`[OpaService] Fetching data via local proxy...`);

        // Call our own backend. This avoids CORS because it's same-origin.
        const response = await fetch('/api/dashboard-data');

        if (!response.ok) {
           throw new Error(`Proxy error: ${response.status}`);
        }

        const data = await response.json();

        // Data comes pre-structured from our server proxy
        const rawTickets = data.tickets || [];
        const rawAttendants = data.attendants || [];

        console.log(`[OpaService] Tickets received: ${rawTickets.length}`);

        // Map Tickets
        const tickets: Ticket[] = rawTickets.map((t: any) => {
           return {
              id: String(t._id || t.id),
              protocol: t.protocolo || t.protocol || `PROT-${t._id?.substring(0,6)}`,
              clientName: t.id_cliente?.nome || t.client_name || 'Cliente Desconhecido',
              contact: t.id_cliente?.cpf_cnpj || t.id_cliente?.telefone || t.contact || 'N/A',
              waitTimeSeconds: calculateSeconds(t.date || t.created_at || t.started_at),
              durationSeconds: (t.status === 'EA') ? calculateSeconds(t.date) : undefined,
              status: mapApiStatus(t.status),
              attendantName: t.id_atendente?.nome || t.attendant_name,
              department: t.setor?.toString() || 'Geral'
           };
        }).filter((t: Ticket) => t.status !== 'finished');

        // Map Attendants
        let attendants: Attendant[] = rawAttendants.map((a: any) => ({
          id: String(a._id || a.id),
          name: a.nome || a.name || 'Agente',
          status: (a.status === 'ativo' || a.status === 'online' || a.is_online) ? 'online' : 'busy',
          activeChats: 0
        }));

        // Fallback: If agents endpoint failed (empty array), try to extract from active tickets
        if (attendants.length === 0 && tickets.length > 0) {
           const agentMap = new Map<string, number>();
           tickets.forEach(t => {
              if (t.status === 'in_service' && t.attendantName) {
                 agentMap.set(t.attendantName, (agentMap.get(t.attendantName) || 0) + 1);
              }
           });

           agentMap.forEach((count, name) => {
              attendants.push({
                 id: `inf-${name}`,
                 name,
                 status: 'online',
                 activeChats: count
              });
           });
        }

        return { tickets, attendants };

      } catch (error) {
        console.warn("[OpaService] Proxy connection issue, falling back to mock:", error);
      }
    }

    // 2. Mock Data Fallback (if no config or error)
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve({
          tickets: generateMockTickets(),
          attendants: generateMockAttendants()
        });
      }, 500); 
    });
  }
};

import express from 'express';
import mysql from 'mysql2/promise';
import bcrypt from 'bcryptjs';
import cors from 'cors';
import dotenv from 'dotenv';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

// Configuração para obter __dirname em módulos ES
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

dotenv.config();

// IMPORTANTE: Ignora erros de certificado SSL auto-assinados ou inválidos na API de destino
// Isso resolve a maioria dos erros "fetch failed" em ambientes corporativos
process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0';

const app = express();
const port = process.env.PORT || 3000;

// Middlewares
app.use(cors());
app.use(express.json());
app.use(express.static(join(__dirname, 'dist')));

// Configuração do Banco de Dados
const dbConfig = {
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'opadashboard',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
};

// Pool de conexão
const pool = mysql.createPool(dbConfig);

// Inicialização do Banco de Dados
async function initDB() {
  try {
    const connection = await pool.getConnection();
    console.log('Conectado ao MySQL com sucesso.');

    // Criar tabela de usuários
    await connection.query(`
      CREATE TABLE IF NOT EXISTS users (
        id INT AUTO_INCREMENT PRIMARY KEY,
        username VARCHAR(255) NOT NULL UNIQUE,
        password_hash VARCHAR(255) NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);

    // Criar tabela de configurações
    await connection.query(`
      CREATE TABLE IF NOT EXISTS settings (
        id INT AUTO_INCREMENT PRIMARY KEY,
        api_url VARCHAR(255),
        api_token TEXT,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      )
    `);

    // Verificar se existe usuário padrão
    const [rows] = await connection.query('SELECT * FROM users WHERE username = ?', ['suporte']);

    // @ts-ignore
    if (rows.length === 0) {
      const salt = await bcrypt.genSalt(10);
      const hash = await bcrypt.hash('200616', salt);
      await connection.query('INSERT INTO users (username, password_hash) VALUES (?, ?)', ['suporte', hash]);
      console.log('Usuário padrão "suporte" criado com sucesso.');
    }

    connection.release();
  } catch (error) {
    console.error('Erro fatal ao conectar no banco de dados. Verifique as credenciais no .env');
    console.error(error);
  }
}

// Inicializa o DB ao arrancar
initDB();

// --- Rotas da API ---

// Login
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;

  try {
    const [rows] = await pool.query('SELECT * FROM users WHERE username = ?', [username]);
    // @ts-ignore
    const user = rows[0];

    if (!user) {
      return res.status(401).json({ success: false, error: 'Usuário não encontrado' });
    }

    const validPassword = await bcrypt.compare(password, user.password_hash);
    if (!validPassword) {
      return res.status(401).json({ success: false, error: 'Senha incorreta' });
    }

    res.json({ success: true, username: user.username });
  } catch (error) {
    console.error(error);
    res.status(500).json({ success: false, error: 'Erro interno no login' });
  }
});

// Obter Configurações
app.get('/api/settings', async (req, res) => {
  try {
    const [rows] = await pool.query('SELECT api_url, api_token FROM settings ORDER BY id DESC LIMIT 1');
    // @ts-ignore
    const config = rows[0] || {};
    res.json(config);
  } catch (error) {
    res.status(500).json({ error: 'Erro ao buscar configurações' });
  }
});

// Salvar Configurações (Requer senha para segurança extra)
app.post('/api/settings', async (req, res) => {
  const { username, password, api_url, api_token } = req.body;

  try {
    // 1. Revalidar credenciais antes de permitir alteração
    const [userRows] = await pool.query('SELECT * FROM users WHERE username = ?', [username]);
    // @ts-ignore
    const user = userRows[0];

    if (!user || !(await bcrypt.compare(password, user.password_hash))) {
      return res.status(403).json({ success: false, error: 'Credenciais inválidas para salvar alterações.' });
    }

    // 2. Salvar ou Atualizar
    // Verifica se já existe config
    const [settingRows] = await pool.query('SELECT id FROM settings LIMIT 1');
    // @ts-ignore
    if (settingRows.length > 0) {
      await pool.query('UPDATE settings SET api_url = ?, api_token = ? WHERE id = ?', [api_url, api_token, settingRows[0].id]);
    } else {
      await pool.query('INSERT INTO settings (api_url, api_token) VALUES (?, ?)', [api_url, api_token]);
    }

    res.json({ success: true });
  } catch (error) {
    console.error(error);
    res.status(500).json({ success: false, error: 'Erro ao salvar configurações' });
  }
});

// Rota Proxy para contornar CORS
app.get('/api/dashboard-data', async (req, res) => {
  try {
    // 1. Obter credenciais do banco
    const [rows] = await pool.query('SELECT api_url, api_token FROM settings ORDER BY id DESC LIMIT 1');
    // @ts-ignore
    const config = rows[0];

    // Se não tiver configuração, retorna 400 (Bad Request) em vez de crashar
    if (!config || !config.api_url || !config.api_token) {
      return res.status(400).json({ error: 'Configurações de API (URL/Token) não encontradas no banco de dados.' });
    }

    const baseUrl = config.api_url.replace(/\/$/, '').trim();
    const headers = { 
      'Authorization': `Bearer ${config.api_token.trim()}`,
      'Content-Type': 'application/json'
    };

    console.log(`[Proxy] Buscando dados em: ${baseUrl}`);

    // 2. Buscar dados no servidor externo
    // Adicionei tratamento de erro individual para cada fetch
    const [ticketsRes, attendantsRes] = await Promise.allSettled([
      fetch(`${baseUrl}/api/v1/atendimento`, { headers }), 
      fetch(`${baseUrl}/api/v1/atendente`, { headers })
    ]);

    let ticketsData = [];
    let attendantsData = [];

    // Helper para processar resposta
    const processResponse = async (result, contextName) => {
      if (result.status === 'fulfilled') {
        const response = result.value;
        if (response.ok) {
          try {
            const text = await response.text();
            // Tenta parsear JSON
            try {
              const json = JSON.parse(text);
              return Array.isArray(json) ? json : (json.data || json.items || []);
            } catch (e) {
              console.warn(`[Proxy] Resposta da API ${contextName} não é um JSON válido:`, text.substring(0, 100));
              return [];
            }
          } catch (e) {
            console.error(`[Proxy] Erro ao ler corpo da resposta ${contextName}:`, e);
            return [];
          }
        } else {
          console.warn(`[Proxy] Erro HTTP API ${contextName}: ${response.status} ${response.statusText}`);
          return [];
        }
      } else {
        console.error(`[Proxy] Falha na conexão ${contextName}:`, result.reason);
        return [];
      }
    };

    ticketsData = await processResponse(ticketsRes, 'Tickets');
    attendantsData = await processResponse(attendantsRes, 'Atendentes');

    // 3. Retornar dados combinados para o frontend
    res.json({
      success: true,
      tickets: ticketsData,
      attendants: attendantsData
    });

  } catch (error) {
    // Retorna o erro detalhado para o frontend poder debugar no "Network Tab"
    console.error('[Proxy] Erro Crítico 500:', error);
    res.status(500).json({ 
      error: 'Erro interno no servidor proxy.', 
      details: error.message,
      stack: process.env.NODE_ENV === 'development' ? error.stack : undefined
    });
  }
});

// SPA Fallback
app.get('*', (req, res) => {
  res.sendFile(join(__dirname, 'dist', 'index.html'));
});

app.listen(port, () => {
  console.log(`Servidor rodando na porta ${port}`);
});

