// Formata telefone BR (55 + DDD + Numero)
function formatPhoneNumber(phone: string): string {
  if (!phone) return phone;
  // Remove caracteres não numéricos
  const nums = phone.replace(/\D/g, '');

  // Verifica se é celular BR (55 + 2 digitos DDD + 9 digitos numero)
  const mobileMatch = nums.match(/^55(\d{2})(\d{5})(\d{4})$/);
  if (mobileMatch) {
    return `(${mobileMatch[1]}) ${mobileMatch[2]}-${mobileMatch[3]}`;
  }

  // Verifica se é fixo BR (55 + 2 digitos DDD + 8 digitos numero)
  const landlineMatch = nums.match(/^55(\d{2})(\d{4})(\d{4})$/);
  if (landlineMatch) {
    return `(${landlineMatch[1]}) ${landlineMatch[2]}-${landlineMatch[3]}`;
  }

  return phone;
}

// Mapeia Status
function mapApiStatus(statusRaw?: any): TicketStatus {
  if (!statusRaw) return 'waiting'; 
  const s = String(statusRaw).toUpperCase().trim();

  // Em Atendimento
  if (s === 'EA' || s === 'EM ATENDIMENTO' || s === '2') return 'in_service';

  // Finalizado
  if (s === 'F' || s === 'FINALIZADO' || s === '3' || s === '4') return 'finished';

  // Aguardando / Triagem / Pendente
  if (s === 'AG' || s === 'AGUARDANDO' || s === 'T' || s === '1') return 'waiting';

  return 'waiting';
}

export const opaService = {
  fetchData: async (config: AppConfig): Promise<{ tickets: Ticket[], attendants: Attendant[] }> => {
    if (config.apiUrl && config.apiToken) {
      try {
        const response = await fetch('/api/dashboard-data');
        if (!response.ok) throw new Error(`Proxy error: ${response.status}`);

        const data = await response.json();
        const rawTickets = data.tickets || [];
        const rawAttendants = data.attendants || [];

        console.log(`[OpaService] Tickets Brutos: ${rawTickets.length}`);
        if(rawTickets.length > 0) console.log('[OpaService] Exemplo:', rawTickets[0]);

        // 1. Criar mapa de Atendentes (ID -> Nome)
        const attendantMap = new Map<string, string>();

        let attendants: Attendant[] = rawAttendants.map((a: any) => {
          const id = String(a._id || a.id);
          const name = a.nome || a.name || 'Agente';
          attendantMap.set(id, name);

          return {
            id,
            name,
            status: (a.status === 'ativo' || a.is_online || a.situacao === 1) ? 'online' : 'busy',
            activeChats: 0 
          };
        });

        // 2. Mapear Tickets
        const tickets: Ticket[] = rawTickets.map((t: any) => {
           const rawStatus = t.status || t.situacao;
           const status = mapApiStatus(rawStatus);
           const dateField = t.date || t.data_criacao; 

           // Cliente e Contato
           let clientName = 'Cliente';
           let contact = 'N/A';

           // Extrai contato do canal se disponível (ex: 55119999@c.us)
           let channelContact = '';
           if (t.canal_cliente) {
              channelContact = t.canal_cliente.split('@')[0];
           }

           // Tenta pegar dados do objeto id_cliente se existir
           if (t.id_cliente && typeof t.id_cliente === 'object') {
              clientName = t.id_cliente.nome || clientName;
              contact = t.id_cliente.cpf_cnpj || t.id_cliente.telefone || channelContact || contact;
           } else if (t.client_name) {
              clientName = t.client_name;
           }

           // Se contato ainda é N/A, usa o do canal
           if (contact === 'N/A' && channelContact) {
              contact = channelContact;
           }

           // Se o nome for genérico e tivermos o contato, usa o contato formatado como nome
           if (clientName === 'Cliente' && contact !== 'N/A') {
              // Se parece ser um telefone, formata
              if (contact.startsWith('55') && contact.length >= 12) {
                 clientName = formatPhoneNumber(contact);
              } else {
                 clientName = contact;
              }
           }

           // Atendente: Tenta pegar objeto, senão busca no mapa, senão usa 'Atendente'
           let attendantName = undefined;
           if (t.id_atendente && typeof t.id_atendente === 'object') {
              attendantName = t.id_atendente.nome;
           } else if (t.id_atendente) {
              attendantName = attendantMap.get(String(t.id_atendente));
           }

           if (!attendantName && t.id_atendente) {
              attendantName = "Atendente"; 
           }

           return {
              id: String(t._id || t.id),
              protocol: t.protocolo || 'N/A',
              clientName,
              contact: formatPhoneNumber(contact),
              waitTimeSeconds: calculateSeconds(dateField),
              durationSeconds: (status === 'in_service') ? calculateSeconds(dateField) : undefined,
              status,
              attendantName,
              department: typeof t.setor === 'object' ? t.setor?.nome : 'Geral'
           };
        });

        // 3. Filtrar finalizados (Garantia extra no front)
        const activeTickets = tickets.filter(t => t.status !== 'finished');

        // 4. Se não veio lista de atendentes da API, improvisar com base nos tickets
        if (attendants.length === 0 && activeTickets.length > 0) {
           const names = new Set<string>();
           activeTickets.forEach(t => {
             if (t.attendantName && t.status === 'in_service') names.add(t.attendantName);
           });
           attendants = Array.from(names).map((name, i) => ({
             id: `gen-${i}`, name, status: 'online', activeChats: 0
           }));
        }

        return { tickets: activeTickets, attendants };

      } catch (error) {
        console.warn("[OpaService] Erro na conexão, usando Mock:", error);
      }
    }

    // Fallback Mock
    return {
       tickets: generateMockTickets(),
       attendants: generateMockAttendants()
    };
  }
};

import express from 'express';
import mysql from 'mysql2/promise';
import bcrypt from 'bcryptjs';
import cors from 'cors';
import dotenv from 'dotenv';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import https from 'https';
import http from 'http';
import { URL } from 'url';

// Configuração para obter __dirname em módulos ES
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

dotenv.config();

// IMPORTANTE: Ignora erros de certificado SSL auto-assinados ou inválidos na API de destino
process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0';

const app = express();
const port = process.env.PORT || 3000;

// Middlewares
app.use(cors());
app.use(express.json());
app.use(express.static(join(__dirname, 'dist')));

// Configuração do Banco de Dados
const dbConfig = {
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'opadashboard',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
};

// Pool de conexão
const pool = mysql.createPool(dbConfig);

// Inicialização do Banco de Dados
async function initDB() {
  try {
    const connection = await pool.getConnection();
    console.log('Conectado ao MySQL com sucesso.');

    // Criar tabela de usuários
    await connection.query(`
      CREATE TABLE IF NOT EXISTS users (
        id INT AUTO_INCREMENT PRIMARY KEY,
        username VARCHAR(255) NOT NULL UNIQUE,
        password_hash VARCHAR(255) NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);

    // Criar tabela de configurações
    await connection.query(`
      CREATE TABLE IF NOT EXISTS settings (
        id INT AUTO_INCREMENT PRIMARY KEY,
        api_url VARCHAR(255),
        api_token TEXT,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      )
    `);

    // Verificar se existe usuário padrão
    const [rows] = await connection.query('SELECT * FROM users WHERE username = ?', ['suporte']);

    // @ts-ignore
    if (rows.length === 0) {
      const salt = await bcrypt.genSalt(10);
      const hash = await bcrypt.hash('200616', salt);
      await connection.query('INSERT INTO users (username, password_hash) VALUES (?, ?)', ['suporte', hash]);
      console.log('Usuário padrão "suporte" criado com sucesso.');
    }

    connection.release();
  } catch (error) {
    console.error('Erro fatal ao conectar no banco de dados. Verifique as credenciais no .env');
    console.error(error);
  }
}

// Inicializa o DB ao arrancar
initDB();

// --- Rotas da API ---

// Login
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;

  try {
    const [rows] = await pool.query('SELECT * FROM users WHERE username = ?', [username]);
    // @ts-ignore
    const user = rows[0];

    if (!user) {
      return res.status(401).json({ success: false, error: 'Usuário não encontrado' });
    }

    const validPassword = await bcrypt.compare(password, user.password_hash);
    if (!validPassword) {
      return res.status(401).json({ success: false, error: 'Senha incorreta' });
    }

    res.json({ success: true, username: user.username });
  } catch (error) {
    console.error(error);
    res.status(500).json({ success: false, error: 'Erro interno no login' });
  }
});

// Obter Configurações
app.get('/api/settings', async (req, res) => {
  try {
    const [rows] = await pool.query('SELECT api_url, api_token FROM settings ORDER BY id DESC LIMIT 1');
    // @ts-ignore
    const config = rows[0] || {};
    res.json(config);
  } catch (error) {
    res.status(500).json({ error: 'Erro ao buscar configurações' });
  }
});

// Salvar Configurações
app.post('/api/settings', async (req, res) => {
  const { username, password, api_url, api_token } = req.body;

  try {
    const [userRows] = await pool.query('SELECT * FROM users WHERE username = ?', [username]);
    // @ts-ignore
    const user = userRows[0];

    if (!user || !(await bcrypt.compare(password, user.password_hash))) {
      return res.status(403).json({ success: false, error: 'Credenciais inválidas.' });
    }

    const [settingRows] = await pool.query('SELECT id FROM settings LIMIT 1');
    // @ts-ignore
    if (settingRows.length > 0) {
      await pool.query('UPDATE settings SET api_url = ?, api_token = ? WHERE id = ?', [api_url, api_token, settingRows[0].id]);
    } else {
      await pool.query('INSERT INTO settings (api_url, api_token) VALUES (?, ?)', [api_url, api_token]);
    }

    res.json({ success: true });
  } catch (error) {
    console.error(error);
    res.status(500).json({ success: false, error: 'Erro ao salvar configurações' });
  }
});

// Normalizador de URL
const normalizeUrl = (url) => {
  if (!url) return '';
  let clean = url.trim().replace(/\/$/, '');
  clean = clean.replace(/\/api\/v1$/, '');
  clean = clean.replace(/\/api$/, '');
  return clean;
};

// Helper: Request with Body for GET (Opa Suite Requirement)
function requestWithBody(urlStr, method, token, bodyData = null) {
  return new Promise((resolve, reject) => {
    try {
      const url = new URL(urlStr);
      const lib = url.protocol === 'https:' ? https : http;

      const bodyString = bodyData ? JSON.stringify(bodyData) : '';

      const options = {
        method: method,
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
          'Content-Length': Buffer.byteLength(bodyString)
        },
        hostname: url.hostname,
        port: url.port || (url.protocol === 'https:' ? 443 : 80),
        path: url.pathname + url.search,
        rejectUnauthorized: false
      };

      const req = lib.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => {
          let parsedData = null;
          let error = null;

          if (res.statusCode >= 200 && res.statusCode < 300) {
             try {
                parsedData = JSON.parse(data);
             } catch (e) {
                error = 'JSON Parse Error';
             }
          } else {
             error = `HTTP ${res.statusCode}: ${data.substring(0, 100)}`;
          }

          resolve({ 
            ok: !error, 
            status: res.statusCode, 
            data: parsedData,
            error: error 
          });
        });
      });

      req.on('error', (e) => resolve({ ok: false, error: e.message }));

      if (bodyString) {
        req.write(bodyString);
      }
      req.end();

    } catch (e) {
      resolve({ ok: false, error: e.message });
    }
  });
}

// Helpers de Data
const getPastDate = (days) => {
  const date = new Date();
  date.setDate(date.getDate() - days);
  return date.toISOString().split('T')[0]; // YYYY-MM-DD
};

// Rota Proxy Principal
app.get('/api/dashboard-data', async (req, res) => {
  try {
    const [rows] = await pool.query('SELECT api_url, api_token FROM settings ORDER BY id DESC LIMIT 1');
    // @ts-ignore
    const config = rows[0];

    if (!config || !config.api_url || !config.api_token) {
      return res.status(400).json({ error: 'Configurações de API não encontradas.' });
    }

    const baseUrl = normalizeUrl(config.api_url);
    const token = config.api_token.trim();

    // Data de início: 30 dias atrás
    const startDate = getPastDate(30);

    console.log(`[Proxy] Buscando dados em: ${baseUrl}/api/v1/atendimento`);

    // TENTATIVA 1: Filtro Otimizado
    // Adicionado "populate": ["id_cliente"] para trazer o nome do cliente em vez do ID
    const payloadOptimized = {
       "filter": {
          "dataInicialAbertura": startDate,
          "status": { "$ne": "F" }
       },
       "options": { 
          "limit": 500,
          "sort": "-_id",
          "populate": ["id_cliente"]
       }
    };

    // Payload de Fallback
    const payloadFallback = {
        "filter": { "dataInicialAbertura": startDate },
        "options": { 
           "limit": 300, 
           "sort": "-_id",
           "populate": ["id_cliente"]
        }
    };

    // Busca de Atendentes
    const attendantsPromise = requestWithBody(`${baseUrl}/api/v1/atendente`, 'GET', token, null);

    // Busca de Tickets
    let ticketsRes = await requestWithBody(`${baseUrl}/api/v1/atendimento`, 'GET', token, payloadOptimized);

    let tickets = [];
    let attendants = [];
    let debugMsg = "";

    // Lógica de Fallback para Tickets
    if (!ticketsRes.ok || (ticketsRes.data && ticketsRes.data.length === 0)) {
        console.warn(`[Proxy] Tentativa otimizada falhou ou retornou vazio (${ticketsRes.status}). Tentando fallback...`);
        debugMsg += "Optimized failed. ";

        // Tenta sem o filtro $ne
        ticketsRes = await requestWithBody(`${baseUrl}/api/v1/atendimento`, 'GET', token, payloadFallback);

        // Se ainda falhar, tenta sem body nenhum
        if (!ticketsRes.ok && (ticketsRes.status === 400 || ticketsRes.status === 403)) {
           debugMsg += "Fallback failed. Trying simple GET. ";
           ticketsRes = await requestWithBody(`${baseUrl}/api/v1/atendimento?limit=200&sort=-_id&populate=id_cliente`, 'GET', token, null);
        }
    }

    // Processar resposta de Tickets
    if (ticketsRes.ok && ticketsRes.data) {
      if (Array.isArray(ticketsRes.data.data)) {
        tickets = ticketsRes.data.data;
      } else if (Array.isArray(ticketsRes.data)) {
        tickets = ticketsRes.data;
      }
      console.log(`[Proxy] Tickets obtidos com sucesso: ${tickets.length}`);
    } else {
      debugMsg += `Final Failure: ${ticketsRes.error}`;
    }

    // Processar resposta de Atendentes
    const attendantsRes = await attendantsPromise;
    if (attendantsRes.ok && attendantsRes.data) {
      if (Array.isArray(attendantsRes.data.data)) {
        attendants = attendantsRes.data.data;
      } else if (Array.isArray(attendantsRes.data)) {
        attendants = attendantsRes.data;
      }
    }

    // Retornar para o frontend
    res.json({
      success: true,
      tickets: tickets,
      attendants: attendants,
      debug_info: {
        msg: debugMsg,
        tickets_raw_count: tickets.length
      }
    });

  } catch (error) {
    console.error('[Proxy] Erro Crítico:', error);
    res.status(500).json({ error: error.message });
  }
});

// SPA Fallback
app.get('*', (req, res) => {
  res.sendFile(join(__dirname, 'dist', 'index.html'));
});

