interface DashboardProps {
  tickets: Ticket[];
  attendants: Attendant[];
}

const formatTime = (seconds: number) => {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
};

export const Dashboard: React.FC<DashboardProps> = ({ tickets, attendants }) => {
  const stats = useMemo(() => {
    const now = new Date();
    const todayStr = now.toISOString().split('T')[0];
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const waiting = tickets.filter(t => t.status === 'waiting');
    const bot = tickets.filter(t => t.status === 'bot');
    const inService = tickets.filter(t => t.status === 'in_service');
    const finished = tickets.filter(t => t.status === 'finished');

    // Filtros por data
    const finishedToday = finished.filter(t => {
      const d = t.closedAt ? new Date(t.closedAt) : (t.createdAt ? new Date(t.createdAt) : null);
      return d && d.toISOString().split('T')[0] === todayStr;
    });

    const finishedMonth = finished.filter(t => {
      const d = t.closedAt ? new Date(t.closedAt) : (t.createdAt ? new Date(t.createdAt) : null);
      return d && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    // TMA: Tempo Médio de Atendimento (dos finalizados hoje para ser mais real)
    const totalTMA = finishedToday.reduce((acc, curr) => acc + (curr.durationSeconds || 0), 0);
    const avgService = finishedToday.length > 0 ? totalTMA / finishedToday.length : 0;

    const totalWait = waiting.reduce((acc, curr) => acc + curr.waitTimeSeconds, 0);
    const avgWait = waiting.length > 0 ? totalWait : 0;

    // Ranking Top 5 (Baseado no Mês)
    const rankingMap: Record<string, number> = {};
    finishedMonth.forEach(t => {
       if (t.attendantName) rankingMap[t.attendantName] = (rankingMap[t.attendantName] || 0) + 1;
    });
    const ranking = Object.entries(rankingMap)
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 5);

    return {
      waiting, bot, inService,
      onlineCount: attendants.length,
      avgWait: Math.round(waiting.length > 0 ? avgWait / waiting.length : 0),
      avgService: Math.round(avgService),
      finishedToday: finishedToday.length,
      finishedMonth: finishedMonth.length,
      ranking
    };
  }, [tickets, attendants]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      <div className="bg-gradient-to-r from-slate-800 to-slate-900 border border-slate-700 rounded-xl p-5 flex flex-col xl:flex-row items-center justify-between shadow-xl gap-5">
        <div>
          <h2 className="text-xl font-bold text-white flex items-center gap-2"><Activity className="w-6 h-6 text-sky-400" /> Dashboard Operacional</h2>
          <p className="text-slate-400 text-sm">Monitoramento em tempo real e produtividade.</p>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 w-full xl:w-auto">
          <div className="bg-slate-950/40 p-3 rounded-lg border border-slate-800"><p className="text-slate-500 text-[10px] uppercase font-bold mb-1">T.M. Espera</p><div className="flex items-center gap-2"><Timer className="w-4 h-4 text-amber-500" /><p className="text-lg font-mono font-bold text-amber-400">{formatTime(stats.avgWait)}</p></div></div>
          <div className="bg-slate-950/40 p-3 rounded-lg border border-slate-800"><p className="text-slate-500 text-[10px] uppercase font-bold mb-1">T.M. Atendimento</p><div className="flex items-center gap-2"><Headset className="w-4 h-4 text-sky-500" /><p className="text-lg font-mono font-bold text-sky-400">{formatTime(stats.avgService)}</p></div></div>
          <div className="bg-slate-950/40 p-3 rounded-lg border border-slate-800"><p className="text-slate-500 text-[10px] uppercase font-bold mb-1">Finalizados (Dia)</p><div className="flex items-center gap-2"><CheckCircle2 className="w-4 h-4 text-emerald-500" /><p className="text-lg font-mono font-bold text-emerald-400">{stats.finishedToday}</p></div></div>
          <div className="bg-slate-950/40 p-3 rounded-lg border border-slate-800"><p className="text-slate-500 text-[10px] uppercase font-bold mb-1">Finalizados (Mês)</p><div className="flex items-center gap-2"><CalendarCheck className="w-4 h-4 text-violet-400" /><p className="text-lg font-mono font-bold text-violet-400">{stats.finishedMonth}</p></div></div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Em Espera" value={stats.waiting.length} icon={<Clock className="text-amber-500" />} colorClass="text-amber-500" />
        <StatCard title="Com o Bot" value={stats.bot.length} icon={<Bot className="text-violet-500" />} colorClass="text-violet-500" />
        <StatCard title="Em Atendimento" value={stats.inService.length} icon={<Headset className="text-sky-500" />} colorClass="text-sky-500" />
        <StatCard title="Atendentes" value={stats.onlineCount} icon={<Users className="text-emerald-500" />} colorClass="text-emerald-500" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <TicketList title="Em Espera" tickets={stats.waiting} type="waiting" />
