    };

    // BUSCA 2: Tickets FINALIZADOS
    // Alterado o filtro para ser mais abrangente (data_inicio ou data_criacao)
    const historyPayload = {
      "filter": { 
        "status": "F", 
        "data_inicio": { "$gte": startDateStr } 
      },
