    res.json(rows[0] || {});
  } catch (error) { res.status(500).json({ error: 'Erro ao buscar configurações' }); }
});

app.post('/api/settings', async (req, res) => {
  const { username, password, api_url, api_token } = req.body;
  try {
    const [userRows] = await pool.query('SELECT * FROM users WHERE username = ?', [username]);
    // @ts-ignore
    const user = userRows[0];
    if (!user || !(await bcrypt.compare(password, user.password_hash))) return res.status(403).json({ success: false });
    const [settingRows] = await pool.query('SELECT id FROM settings LIMIT 1');
    // @ts-ignore
    if (settingRows.length > 0) await pool.query('UPDATE settings SET api_url = ?, api_token = ? WHERE id = ?', [api_url, api_token, settingRows[0].id]);
    else await pool.query('INSERT INTO settings (api_url, api_token) VALUES (?, ?)', [api_url, api_token]);
    res.json({ success: true });
  } catch (error) { res.status(500).json({ success: false }); }
});

function requestWithBody(urlStr, method, token, bodyData = null) {
  return new Promise((resolve) => {
    try {
      const url = new URL(urlStr);
      const lib = url.protocol === 'https:' ? https : http;
      const bodyString = bodyData ? JSON.stringify(bodyData) : '';
      const options = {
        method,
        headers: { 
          'Authorization': `Bearer ${token}`, 
          'Content-Type': 'application/json', 
          'Content-Length': Buffer.byteLength(bodyString) 
        },
        hostname: url.hostname,
        port: url.port || (url.protocol === 'https:' ? 443 : 80),
        path: url.pathname + url.search,
        rejectUnauthorized: false
      };
      const req = lib.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => {
          try { 
            const parsed = JSON.parse(data);
            resolve({ ok: res.statusCode < 300, data: parsed }); 
          }
          catch (e) { resolve({ ok: false, error: 'JSON Parse' }); }
        });
      });
      req.on('error', (e) => resolve({ ok: false, error: e.message }));
      if (bodyString) req.write(bodyString);
      req.end();
    } catch (e) { resolve({ ok: false, error: e.message }); }
  });
}

app.get('/api/dashboard-data', async (req, res) => {
  try {
    const [rows] = await pool.query('SELECT api_url, api_token FROM settings ORDER BY id DESC LIMIT 1');
    // @ts-ignore
    const config = rows[0];
    if (!config) return res.status(400).json({ error: 'Config missing' });
    const baseUrl = config.api_url.replace(/\/$/, '');
    const token = config.api_token;

    const startDate = new Date();
    startDate.setDate(startDate.getDate() - 30);
    const startDateStr = startDate.toISOString().split('T')[0];

    const [activeRes, historyRes, uRes, dRes] = await Promise.all([
      requestWithBody(`${baseUrl}/api/v1/atendimento`, 'GET', token, {
        "filter": { "status": { "$ne": "F" } },
        "options": { "limit": 1000, "sort": "-_id", "populate": ["id_cliente", "id_atendente", "id_departamento", "setor", "id_contato"] }
      }),
      requestWithBody(`${baseUrl}/api/v1/atendimento`, 'GET', token, {
        "filter": { "status": "F", "data_abertura": { "$gte": startDateStr } },
        "options": { "limit": 5000, "sort": "-_id", "populate": ["id_cliente", "id_atendente", "id_departamento", "setor", "id_contato"] }
      }),
      requestWithBody(`${baseUrl}/api/v1/usuario`, 'GET', token, { "filter": { "status": "A" }, "options": { "limit": 200 } }),
      requestWithBody(`${baseUrl}/api/v1/departamento`, 'GET', token, { "options": { "limit": 100 } })
    ]);

    let activeTickets = activeRes.ok ? (activeRes.data.data || activeRes.data) : [];
    let historyTickets = historyRes.ok ? (historyRes.data.data || historyRes.data) : [];

    if (!Array.isArray(activeTickets)) activeTickets = [];
    if (!Array.isArray(historyTickets)) historyTickets = [];

    res.json({
      success: true,
      tickets: [...activeTickets, ...historyTickets],
      attendants: uRes.ok ? (uRes.data.data || uRes.data) : [],
      departments: dRes.ok ? (dRes.data.data || dRes.data) : []
    });

  } catch (error) { res.status(500).json({ error: error.message }); }
});

app.get('*', (req, res) => res.sendFile(join(__dirname, 'dist', 'index.html')));
app.listen(port, () => console.log(`Dashboard rodando na porta ${port}`));

export type TicketStatus = 'waiting' | 'in_service' | 'finished' | 'bot';

export interface Ticket {
  id: string;
  protocol: string;
  clientName: string;
  contact: string;
  waitTimeSeconds: number; // Time waiting in queue
  durationSeconds?: number; // Time in service
  status: TicketStatus;
  attendantName?: string;
  department?: string;
  // Added optional date fields to store creation and completion times for dashboard analytics
  createdAt?: string;
  closedAt?: string;
}

export interface Attendant {
  id: string;
  name: string;
  status: 'online' | 'offline' | 'busy';
  activeChats: number;
}

export interface DashboardStats {
  waitingCount: number;
  botCount: number;
  inServiceCount: number;
  attendantCount: number;
  avgWaitTimeSeconds: number;
  avgServiceTimeSeconds: number;
}

export interface AppConfig {
  apiUrl: string;
  apiToken: string;
}

import { Ticket, Attendant, AppConfig, TicketStatus } from '../types';

function calculateSeconds(startStr?: string, endStr?: string): number {
  if (!startStr) return 0;
  try {
    const start = new Date(startStr).getTime();
    if (isNaN(start)) return 0;

    // Usamos o tempo do servidor se disponível, ou o tempo local
    const end = endStr ? new Date(endStr).getTime() : new Date().getTime();
    if (isNaN(end)) return 0;

    const diff = Math.floor((end - start) / 1000);
    // Se a diferença for negativa (drift de relógio), retornamos pelo menos 1 segundo se o ticket existir
    return diff > 0 ? diff : 1;
  } catch {
    return 0;
  }
}

function determineTicketStatus(t: any, departmentName?: string): TicketStatus {
  const statusRaw = t.status || t.situacao;
  const s = statusRaw ? String(statusRaw).toUpperCase().trim() : '';

  if (['F', '3', '4', 'FINALIZADO'].includes(s)) return 'finished';
  if (['EA', 'EM ATENDIMENTO', '2'].includes(s)) return 'in_service';
  if (s === 'PS') return 'bot';

  if (['AG', 'AGUARDANDO', 'BOT', 'E', 'EE', 'EM ESPERA', '1', 'T', ''].includes(s)) {
     const hasDept = departmentName && 
                    departmentName !== 'Geral' && 
                    departmentName !== 'Sem Setor' && 
                    departmentName.trim() !== '';
     return hasDept ? 'waiting' : 'bot';
  }

  if (t.id_atendente) return 'in_service';
  return 'bot'; 
}

function formatPhone(phone?: any): string | null {
  if (!phone) return null;
  const p = String(phone).replace(/\D/g, '');
  if (p.length < 8) return p;

  if (p.startsWith('55') && p.length >= 12) {
    const sub = p.substring(2);
    return sub.length === 11 ? `(${sub.substring(0,2)}) ${sub.substring(2,7)}-${sub.substring(7)}` : `(${sub.substring(0,2)}) ${sub.substring(2,6)}-${sub.substring(6)}`;
  } else if (p.length === 11) {
    return `(${p.substring(0,2)}) ${p.substring(2,7)}-${p.substring(7)}`;
  } else if (p.length === 10) {
    return `(${p.substring(0,2)}) ${p.substring(2,6)}-${p.substring(6)}`;
  }
  return p;
}

export const opaService = {
  fetchData: async (config: AppConfig): Promise<{ tickets: Ticket[], attendants: Attendant[] }> => {
    if (!config.apiUrl || !config.apiToken) return { tickets: [], attendants: [] };
    try {
      const response = await fetch('/api/dashboard-data');
      if (!response.ok) return { tickets: [], attendants: [] };
      const data = await response.json();

      const rawTickets = data.tickets || [];
      const rawAttendants = data.attendants || [];
      const rawDepartments = data.departments || [];

      const deptMap = new Map();
      rawDepartments.forEach((d: any) => deptMap.set(String(d._id || d.id), d.nome));

      const attMap = new Map();
      const attendants: Attendant[] = rawAttendants.map((a: any) => {
        const id = String(a._id || a.id);
        const name = a.nome || a.name || 'Agente';
        attMap.set(id, name);
        return { id, name, status: 'online', activeChats: 0 };
      });

      const tickets: Ticket[] = rawTickets.map((t: any) => {
        const rawDept = t.setor || t.id_departamento || t.departamento;
        let deptName = '';
        if (typeof rawDept === 'object' && rawDept?.nome) deptName = rawDept.nome;
        else if (deptMap.has(String(rawDept))) deptName = deptMap.get(String(rawDept));

        const status = determineTicketStatus(t, deptName);

        // MAPEAMENTO DE DATAS (Opa Suite é inconsistente entre versões)
        const dateCreated = t.data_criacao || t.data_abertura || t.createdAt || t.data_cad;
        const dateStarted = t.data_inicio || t.data_atendimento || t.dt_atendimento || t.dt_inicio; 
        const dateEnded = t.data_fechamento || t.data_fim || t.updatedAt || t.data_fin;

        // RESOLUÇÃO DE NOME AVANÇADA
        let nameFound = null;

        // 1. Tentar campos de nome direto
        const prioritizedNames = [
          t.id_cliente?.razao_social,
          t.id_cliente?.nome,
          t.id_contato?.nome,
          t.cliente_nome,
          t.contato_nome,
          t.nome_cliente,
          t.nome
        ];

        for (const n of prioritizedNames) {
          const val = n ? String(n).trim() : '';
          // Se o valor NÃO for o protocolo (ex: ITL...) e NÃO for "Cliente", usamos ele.
          if (val && 
              val.toLowerCase() !== 'cliente' && 
              !/^[A-Z]{2,4}\d{6,}/.test(val) && // Regex mais específica para protocolos Opa
              val.length > 3) {
            nameFound = val;
            break;
          }
        }

        // 2. Se não achou nome real, tentar telefone
        if (!nameFound) {
          const phone = t.id_contato?.fone || t.id_cliente?.fone || t.contato_fone || t.fone;
          const formatted = formatPhone(phone);
          if (formatted && formatted.length > 5) {
            nameFound = formatted;
          }
        }

        // 3. Fallback: Se ainda estiver vazio ou for apenas o protocolo, tenta pegar o protocolo formatado
        if (!nameFound) {
          nameFound = t.protocolo || `Ticket ${String(t._id || t.id).slice(-6)}`;
        }

        let attName = undefined;
        if (t.id_atendente?.nome) attName = t.id_atendente.nome;
        else if (attMap.has(String(t.id_atendente))) attName = attMap.get(String(t.id_atendente));

        return {
          id: String(t._id || t.id),
          protocol: t.protocolo || 'N/A',
          clientName: nameFound,
          contact: '',
          // Espera: da criação ao início. Se ainda não iniciou, usa data atual.
          waitTimeSeconds: calculateSeconds(dateCreated, dateStarted || undefined),
          // Atendimento: do início ao fim. Se ainda ativo, usa data atual.
          // Importante: Se dateStarted for nulo, usamos dateCreated como fallback para evitar zerar o tempo visual
          durationSeconds: calculateSeconds(dateStarted || dateCreated, status === 'finished' ? dateEnded : undefined),
          status,
          attendantName: attName,
          department: deptName || 'Sem Setor',
          createdAt: dateCreated,
          closedAt: dateEnded
        };
      });

      tickets.forEach(t => {
        if (t.status === 'in_service' && t.attendantName) {
          const a = attendants.find(att => att.name === t.attendantName);
          if (a) a.activeChats++;
        }
      });

      return { tickets, attendants };
    } catch (e) {
      console.error("[OpaService] Erro fatal:", e);
      return { tickets: [], attendants: [] };
    }
  }
};

import React, { useMemo } from 'react';
import { Ticket, Attendant } from '../types';
import { StatCard } from './StatCard';
import { TicketList } from './TicketList';
import { Clock, Users, Headset, Timer, Bot, Activity, CalendarCheck, CheckCircle2, Trophy } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DashboardProps {
  tickets: Ticket[];
  attendants: Attendant[];
}

const formatTime = (seconds: number) => {
  if (!seconds || seconds <= 0) return "00:00:00";
  // Limite de 48 horas para evitar anomalias
  if (seconds > 172800) seconds = 172800;
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
};

export const Dashboard: React.FC<DashboardProps> = ({ tickets, attendants }) => {
  const stats = useMemo(() => {
    // Pegamos a data local no formato YYYY-MM-DD
    const today = new Date();
    const todayStr = today.toLocaleDateString('en-CA'); // en-CA retorna YYYY-MM-DD
    const currentMonth = today.getMonth();
    const currentYear = today.getFullYear();

    const waiting = tickets.filter(t => t.status === 'waiting');
    const bot = tickets.filter(t => t.status === 'bot');
    const inService = tickets.filter(t => t.status === 'in_service');
    const finished = tickets.filter(t => t.status === 'finished');

    // Filtro de Finalizados hoje usando data local
    const finishedToday = finished.filter(t => {
      const dStr = t.closedAt || t.createdAt;
      if (!dStr) return false;
      const d = new Date(dStr);
      return d.toLocaleDateString('en-CA') === todayStr;
    });

    const finishedMonth = finished.filter(t => {
      const dStr = t.closedAt || t.createdAt;
      if (!dStr) return false;
      const d = new Date(dStr);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    // TMA: Média dos atendimentos concluídos (considerando tickets de hoje para ser mais reativo)
    const validDurations = finished
      .map(t => t.durationSeconds || 0)
      .filter(d => d > 2 && d < 28800); // 2 seg a 8 horas

    const totalTMA = validDurations.reduce((acc, curr) => acc + curr, 0);
    const avgService = validDurations.length > 0 ? totalTMA / validDurations.length : 0;

    // TME: Tempo Médio de Espera dos que estão aguardando AGORA
    const currentWaitingDurations = waiting.map(t => t.waitTimeSeconds).filter(d => d > 0);
    const totalWait = currentWaitingDurations.reduce((acc, curr) => acc + curr, 0);
    const avgWait = currentWaitingDurations.length > 0 ? totalWait / currentWaitingDurations.length : 0;

    const rankingMap: Record<string, number> = {};
    finishedMonth.forEach(t => {
       if (t.attendantName) rankingMap[t.attendantName] = (rankingMap[t.attendantName] || 0) + 1;
    });
    const ranking = Object.entries(rankingMap)
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 5);

    return {
      waiting, bot, inService,
      onlineCount: attendants.length,
      avgWait: Math.round(avgWait),
      avgService: Math.round(avgService),
      finishedToday: finishedToday.length,
      finishedMonth: finishedMonth.length,
      ranking
    };
  }, [tickets, attendants]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      {/* Header Stat Cards */}
      <div className="bg-gradient-to-r from-slate-800 to-slate-900 border border-slate-700 rounded-xl p-5 flex flex-col xl:flex-row items-center justify-between shadow-xl gap-5">
        <div>
          <h2 className="text-xl font-bold text-white flex items-center gap-2"><Activity className="w-6 h-6 text-sky-400" /> Dashboard Operacional</h2>
          <p className="text-slate-400 text-sm">Monitoramento de produtividade em tempo real.</p>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 w-full xl:w-auto">
          <div className="bg-slate-950/40 p-3 rounded-lg border border-slate-800 min-w-[150px]">
            <p className="text-slate-500 text-[10px] uppercase font-bold mb-1">T.M. Espera (Fila)</p>
            <div className="flex items-center gap-2"><Timer className="w-4 h-4 text-amber-500" /><p className="text-lg font-mono font-bold text-amber-400">{formatTime(stats.avgWait)}</p></div>
          </div>
          <div className="bg-slate-950/40 p-3 rounded-lg border border-slate-800 min-w-[150px]">
            <p className="text-slate-500 text-[10px] uppercase font-bold mb-1">T.M. Atendimento</p>
            <div className="flex items-center gap-2"><Headset className="w-4 h-4 text-sky-500" /><p className="text-lg font-mono font-bold text-sky-400">{formatTime(stats.avgService)}</p></div>
          </div>
          <div className="bg-slate-950/40 p-3 rounded-lg border border-slate-800 min-w-[150px]">
            <p className="text-slate-500 text-[10px] uppercase font-bold mb-1">Finalizados (Hoje)</p>
            <div className="flex items-center gap-2"><CheckCircle2 className="w-4 h-4 text-emerald-500" /><p className="text-lg font-mono font-bold text-emerald-400">{stats.finishedToday}</p></div>
          </div>
          <div className="bg-slate-950/40 p-3 rounded-lg border border-slate-800 min-w-[150px]">
            <p className="text-slate-500 text-[10px] uppercase font-bold mb-1">Finalizados (Mês)</p>
            <div className="flex items-center gap-2"><CalendarCheck className="w-4 h-4 text-violet-400" /><p className="text-lg font-mono font-bold text-violet-400">{stats.finishedMonth}</p></div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Em Espera" value={stats.waiting.length} icon={<Clock className="text-amber-500" />} colorClass="text-amber-500" />
        <StatCard title="Com o Bot" value={stats.bot.length} icon={<Bot className="text-violet-500" />} colorClass="text-violet-500" />
        <StatCard title="Em Atendimento" value={stats.inService.length} icon={<Headset className="text-sky-500" />} colorClass="text-sky-500" />
        <StatCard title="Atendentes" value={stats.onlineCount} icon={<Users className="text-emerald-500" />} colorClass="text-emerald-500" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <TicketList title="Em Espera" tickets={stats.waiting} type="waiting" />
        <TicketList title="Com o Bot" tickets={stats.bot} type="bot" />
        <TicketList title="Em Atendimento" tickets={stats.inService} type="in_service" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
        <div className="bg-slate-800 border border-slate-700 rounded-xl p-6 shadow-lg h-64">
           <p className="text-xs uppercase text-slate-500 font-bold mb-4 flex items-center gap-2"><Activity className="w-4 h-4" /> Distribuição de Volume</p>
           <ResponsiveContainer width="100%" height="80%">
             <BarChart data={[
               {name:'Espera',v:stats.waiting.length,c:'#f59e0b'},
               {name:'Bot',v:stats.bot.length,c:'#8b5cf6'},
               {name:'Ativos',v:stats.inService.length,c:'#0ea5e9'}
             ]} layout="vertical">
