function requestWithBody(urlStr, method, token, bodyData = null) {
  return new Promise((resolve) => {
    try {
      const url = new URL(urlStr);
      const lib = url.protocol === 'https:' ? https : http;
      const bodyString = bodyData ? JSON.stringify(bodyData) : '';
      const options = {
        method,
        headers: { 
          'Authorization': `Bearer ${token}`, 
          'Content-Type': 'application/json', 
          'Content-Length': Buffer.byteLength(bodyString) 
        },
        hostname: url.hostname,
        port: url.port || (url.protocol === 'https:' ? 443 : 80),
        path: url.pathname + url.search,
        rejectUnauthorized: false
      };
      const req = lib.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => {
          try { 
            const parsed = JSON.parse(data);
            resolve({ ok: res.statusCode < 300, data: parsed }); 
          }
          catch (e) { resolve({ ok: false, error: 'JSON Parse Error' }); }
        });
      });
      req.on('error', (e) => resolve({ ok: false, error: e.message }));
      if (bodyString) req.write(bodyString);
      req.end();
    } catch (e) { resolve({ ok: false, error: e.message }); }
  });
}

app.get('/api/dashboard-data', async (req, res) => {
  try {
    const [rows] = await pool.query('SELECT api_url, api_token FROM settings ORDER BY id DESC LIMIT 1');
    // @ts-ignore
    const config = rows[0];
    if (!config) return res.status(400).json({ error: 'Config missing' });

    const baseUrl = config.api_url.replace(/\/$/, '');
    const token = config.api_token;

    const dateLimit = new Date();
    dateLimit.setDate(dateLimit.getDate() - 7);
    const dateLimitStr = dateLimit.toISOString().split('T')[0];

    const populate = ["id_cliente", "id_atendente", "id_motivo_atendimento", "setor", "id_contato"];

    const [activeRes, historyRes, uRes, clientRes, contactRes] = await Promise.all([
      requestWithBody(`${baseUrl}/api/v1/atendimento`, 'GET', token, {
        "filter": { "status": { "$ne": "F" } },
        "options": { "limit": 500, "populate": populate, "sort": "-_id" }
      }),
      requestWithBody(`${baseUrl}/api/v1/atendimento`, 'GET', token, {
        "filter": { "status": "F", "dataInicialAbertura": dateLimitStr },
        "options": { "limit": 500, "populate": populate, "sort": "-_id" } // ADICIONADO SORT AQUI
      }),
      requestWithBody(`${baseUrl}/api/v1/usuario`, 'GET', token, {
        "filter": { "status": "A" },
        "options": { "limit": 100 }
      }),
      requestWithBody(`${baseUrl}/api/v1/cliente`, 'GET', token, {
        "options": { "limit": 1000, "sort": "-_id" }
      }),
      requestWithBody(`${baseUrl}/api/v1/contato`, 'GET', token, {
        "options": { "limit": 1000, "sort": "-_id" }
      })
    ]);

    const getList = (res) => {
      if (!res.ok) return [];
      return res.data.data || res.data || [];
    };

    res.json({
      success: true,
      tickets: [...getList(activeRes), ...getList(historyRes)],
      attendants: getList(uRes),
      clients: getList(clientRes),
      contacts: getList(contactRes)
    });

  } catch (error) { 
    res.status(500).json({ error: error.message }); 
  }
});

