              />
              <Bar dataKey="count" radius={[0, 4, 4, 0]} barSize={24}>
                {stats.ranking.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={index === 0 ? '#38bdf8' : '#0ea5e9'} />
