    const avgService = validFinished.length > 0 ? totalTMA / validFinished.length : 0;

    const totalWait = waiting.reduce((acc, curr) => acc + curr.waitTimeSeconds, 0);
    const avgWait = waiting.length > 0 ? totalWait / waiting.length : 0;

