      waiting, bot, inService,
      avgWait: Math.round(avgWait),
      avgService: Math.round(avgService),
      finishedToday: finishedToday.length,
      finishedMonth: finishedMonth.length,
      ranking,
      topTechnician,
      departmentSummary: Object.values(deptSummary),
