import express from 'express';
import mysql from 'mysql2/promise';
import bcrypt from 'bcryptjs';
import cors from 'cors';
import dotenv from 'dotenv';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import https from 'https';
import http from 'http';
import { URL } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

dotenv.config();
process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0';

const app = express();
const port = process.env.PORT || 3000;

const dbConfig = {
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'opadashboard',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
};

const pool = mysql.createPool(dbConfig);

async function initDB() {
  try {
    const connection = await pool.getConnection();
    await connection.query(`CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)`);
    await connection.query(`CREATE TABLE IF NOT EXISTS settings (id INT AUTO_INCREMENT PRIMARY KEY, api_url VARCHAR(255), api_token TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)`);
    const [rows] = await connection.query('SELECT * FROM users WHERE username = ?', ['suporte']);
    if (rows.length === 0) {
      const salt = await bcrypt.genSalt(10);
      const hash = await bcrypt.hash('200616', salt);
      await connection.query('INSERT INTO users (username, password_hash) VALUES (?, ?)', ['suporte', hash]);
    }
    connection.release();
  } catch (error) { console.error("Erro ao inicializar banco:", error.message); }
}
initDB();

app.use(cors());
app.use(express.json());
app.use(express.static(join(__dirname, 'dist')));

async function opaRequest(baseUrl, path, token, body = {}) {
  return new Promise((resolve) => {
    try {
      let finalUrlStr = baseUrl.replace(/\/$/, '');
      if (!finalUrlStr.endsWith(path)) finalUrlStr += path;

      const url = new URL(finalUrlStr);
      const lib = url.protocol === 'https:' ? https : http;

      const jsonBody = JSON.stringify(body);

      const options = {
        method: 'GET',
        headers: { 
          'Authorization': token.startsWith('Bearer ') ? token : `Bearer ${token}`,
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(jsonBody)
        },
        hostname: url.hostname,
        port: url.port || (url.protocol === 'https:' ? 443 : 80),
        path: url.pathname,
        rejectUnauthorized: false,
        timeout: 25000 
      };

      const req = lib.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => {
          try { 
            const parsed = JSON.parse(data);
            if (res.statusCode >= 400) {
                resolve({ ok: false, error: parsed, status: res.statusCode });
            } else {
                resolve({ ok: true, data: parsed }); 
            }
          }
          catch (e) { 
            resolve({ ok: false, error: 'JSON Parse Error', raw: data }); 
          }
        });
      });

      req.on('error', (e) => resolve({ ok: false, error: e.message }));
      req.on('timeout', () => {
        req.destroy();
        resolve({ ok: false, error: 'Timeout' });
      });

      req.write(jsonBody);
      req.end();
    } catch (e) { 
      resolve({ ok: false, error: e.message }); 
    }
  });
}

app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  try {
    const [rows] = await pool.query('SELECT * FROM users WHERE username = ?', [username]);
    const user = rows[0];
    if (!user || !(await bcrypt.compare(password, user.password_hash))) return res.status(401).json({ success: false, error: 'Credenciais inválidas' });
    res.json({ success: true, username: user.username });
  } catch (error) { res.status(500).json({ success: false }); }
});

app.get('/api/settings', async (req, res) => {
  try {
    const [rows] = await pool.query('SELECT api_url, api_token FROM settings ORDER BY id DESC LIMIT 1');
    res.json(rows[0] || {});
  } catch (error) { res.status(500).json({ error: 'Erro ao buscar configurações' }); }
});

app.post('/api/settings', async (req, res) => {
  const { username, password, api_url, api_token } = req.body;
  try {
    const [userRows] = await pool.query('SELECT * FROM users WHERE username = ?', [username]);
    const user = userRows[0];
    if (!user || !(await bcrypt.compare(password, user.password_hash))) return res.status(403).json({ success: false });
    const [settingRows] = await pool.query('SELECT id FROM settings LIMIT 1');
    if (settingRows.length > 0) await pool.query('UPDATE settings SET api_url = ?, api_token = ? WHERE id = ?', [api_url, api_token, settingRows[0].id]);
    else await pool.query('INSERT INTO settings (api_url, api_token) VALUES (?, ?)', [api_url, api_token]);
    res.json({ success: true });
  } catch (error) { res.status(500).json({ success: false }); }
});

app.get('/api/dashboard-data', async (req, res) => {
  try {
    const [rows] = await pool.query('SELECT api_url, api_token FROM settings ORDER BY id DESC LIMIT 1');
    const config = rows[0];
    if (!config || !config.api_url) return res.status(400).json({ error: 'Configuração pendente' });

    let baseUrl = config.api_url.trim().replace(/\/$/, '');
    if (!baseUrl.includes('/api/v1')) baseUrl += '/api/v1';
    const token = config.api_token;

    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const dateFilter = `${year}-${month}-01 00:00:00`;

    const ROBOT_ID = '5d1642ad4b16a50312cc8f4d';

    // 1. ATIVOS
    const activeRes = await opaRequest(baseUrl, '/atendimento', token, {
      filter: { status: { $ne: 'F' } },
      options: { limit: 1000, sort: { date: -1 } }
    });

    // 2. FINALIZADOS
    const finishedRes = await opaRequest(baseUrl, '/atendimento', token, {
      filter: {
        status: 'F',
        date: { $gte: dateFilter }, 
        id_atendente: { $ne: ROBOT_ID }
      },
      options: { limit: 3000, sort: { date: -1 } }
    });

    // 3. USUÁRIOS
    const userRes = await opaRequest(baseUrl, '/usuario', token, {
      options: { limit: 300 }
    });

    // 4. DEPARTAMENTOS
    const deptRes = await opaRequest(baseUrl, '/departamento', token, {
        options: { limit: 300 }
    });

    // 5. PERÍODOS
    const periodRes = await opaRequest(baseUrl, '/atendimento/periodo', token, {
        options: { limit: 100 }
    });

    const getList = (res) => {
      if (res.ok && res.data?.status === "success") return res.data.data || [];
      if (res.ok && Array.isArray(res.data)) return res.data;
      return [];
    };

    const isRobot = (t) => {
      const attId = typeof t.id_atendente === 'object' ? String(t.id_atendente?._id || '') : String(t.id_atendente || '');
      const attName = typeof t.id_atendente === 'object' ? String(t.id_atendente?.nome || '') : '';
      return attId === ROBOT_ID || attName.toLowerCase().includes('robô') || attName.toLowerCase().includes('robot');
    };

    const sortByDateDesc = (a, b) => {
        const dateA = new Date(String(a.date || '').replace(' ', 'T')).getTime();
        const dateB = new Date(String(b.date || '').replace(' ', 'T')).getTime();
        return dateB - dateA;
    };

    const rawActive = getList(activeRes).sort(sortByDateDesc);
    const rawFinished = getList(finishedRes).sort(sortByDateDesc);
    const departments = getList(deptRes);
    const periods = getList(periodRes);

    const activeTickets = rawActive.filter(t => !isRobot(t));
    const finishedTickets = rawFinished.filter(t => !isRobot(t));

    const attendants = getList(userRes).filter(a => {
        const id = String(a._id || a.id);
        const nome = String(a.nome || '');
        return id !== ROBOT_ID && !nome.toLowerCase().includes('robô');
    });

    res.json({
      success: true,
      tickets: [...activeTickets, ...finishedTickets],
      attendants: attendants,
      departments: departments,
      periods: periods
    });

  } catch (error) { 
    res.status(500).json({ success: false, error: error.message }); 
  }
});

app.get('*', (req, res) => res.sendFile(join(__dirname, 'dist', 'index.html')));
app.listen(port, () => console.log(`Backend rodando na porta ${port}`));

import React, { useMemo, useEffect } from 'react';
import { Ticket, Attendant, Department } from '../types';
import { StatCard } from './StatCard';
import { TicketList } from './TicketList';
import { Clock, Headset, Timer, Bot, Activity, CalendarCheck, CheckCircle2, BarChart3, Star, ListFilter } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DashboardProps {
  tickets: Ticket[];
  attendants: Attendant[];
  departments: Department[];
  periods: any[];
}

const formatTime = (seconds: number) => {
  if (typeof seconds !== 'number' || seconds <= 0) return "00:00:00";
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
};

export const Dashboard: React.FC<DashboardProps> = ({ tickets, attendants, departments, periods }) => {
  const stats = useMemo(() => {
    const now = new Date();
    const offset = now.getTimezoneOffset() * 60000;
    const todayStr = new Date(now.getTime() - offset).toISOString().split('T')[0];

    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const waiting = tickets.filter(t => t.status === 'waiting');
    const bot = tickets.filter(t => t.status === 'bot');
    const inService = tickets.filter(t => t.status === 'in_service');
    const finished = tickets.filter(t => t.status === 'finished');

    const finishedToday = finished.filter(t => {
      const dateStr = t.closedAt || t.createdAt;
      return dateStr && String(dateStr).startsWith(todayStr.substring(0, 10));
    });

    const finishedMonth = finished.filter(t => {
      const dateStr = t.closedAt || t.createdAt;
      if (!dateStr) return false;
      const d = new Date(String(dateStr).replace(' ', 'T'));
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const deptSummary: Record<string, { setor: string, id_setor: string, bot: number, aguardando: number }> = {};
    const detailedLogs: any[] = [];

    tickets.forEach(t => {
      if (t.status === 'bot' || t.status === 'waiting') {
        const key = t.departmentId || 'unassigned';
        if (!deptSummary[key]) {
          deptSummary[key] = { setor: t.department || 'Desconhecido', id_setor: t.departmentId || 'N/A', bot: 0, aguardando: 0 };
        }
        if (t.status === 'bot') deptSummary[key].bot++;
        if (t.status === 'waiting') deptSummary[key].aguardando++;

        detailedLogs.push({
            protocolo: t.protocol,
            cliente: t.clientName,
            status: t.status === 'bot' ? 'EM BOT' : 'AGUARDANDO',
            id_setor: t.departmentId,
            setor: t.department
        });
      }
    });

    const rankingMap: Record<string, number> = {};
    finishedMonth.forEach(t => {
       if (t.attendantName) {
         rankingMap[t.attendantName] = (rankingMap[t.attendantName] || 0) + 1;
       }
    });

    const ranking = Object.entries(rankingMap)
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 10);

    const topTechnician = ranking.length > 0 ? ranking[0] : null;

    const validFinished = finished.filter(t => (t.durationSeconds || 0) > 0);
    const totalTMA = validFinished.reduce((acc, curr) => acc + (curr.durationSeconds || 0), 0);
    const avgService = validFinished.length > 0 ? totalTMA / validFinished.length : 0;

    const totalWait = waiting.reduce((acc, curr) => acc + curr.waitTimeSeconds, 0);
    const avgWait = waiting.length > 0 ? totalWait / waiting.length : 0;

    return {
      waiting, bot, inService, finished,
      avgWait: Math.round(avgWait),
      avgService: Math.round(avgService),
      finishedToday: finishedToday.length,
      finishedMonth: finishedMonth.length,
      ranking,
      topTechnician,
      departmentSummary: Object.values(deptSummary),
      detailedLogs: detailedLogs.sort((a, b) => a.id_setor.localeCompare(b.id_setor))
    };
  }, [tickets, attendants]);

  useEffect(() => {
    console.clear();
    console.group("📂 OPA SUITE - MASTER LOG (F12)");

    if (departments.length > 0) {
      console.log("%c--- LISTA COMPLETA DE SETORES (MASTER LIST) ---", "color: #38bdf8; font-weight: bold;");
      console.table(departments.map(d => ({ "ID DO SETOR": d.id, "NOME DO SETOR": d.name })));
    }

    if (periods && periods.length > 0) {
      console.log("%c--- LISTA DE PERÍODOS CONFIGURADOS ---", "color: #a78bfa; font-weight: bold;");
      console.table(periods.map(p => ({ "ID PERÍODO": p._id, "NOME": p.nome, "ATIVO": p.ativo })));
    }

    if (stats.finished.length > 0) {
      console.log("%c--- DIAGNÓSTICO DE ATENDIMENTOS FINALIZADOS ---", "color: #10b981; font-weight: bold;");

      const ticketsWithTS = stats.finished.map(t => ({
          ...t,
          ts: new Date(String(t.createdAt).replace(' ', 'T')).getTime()
      }));

      const newest = ticketsWithTS.reduce((prev, curr) => prev.ts > curr.ts ? prev : curr);
      const oldest = ticketsWithTS.reduce((prev, curr) => prev.ts < curr.ts ? prev : curr);

      console.log("Total carregado:", stats.finished.length);
      console.log("%cChamado MAIS RECENTE detectado:", "color: #34d399;", {
        Protocolo: newest.protocol,
        Abertura: newest.createdAt,
        Fechamento: newest.closedAt,
        Atendente: newest.attendantName
      });
      console.log("%cChamado MAIS ANTIGO detectado:", "color: #fb7185;", {
        Protocolo: oldest.protocol,
        Abertura: oldest.createdAt,
        Fechamento: oldest.closedAt,
        Atendente: oldest.attendantName
      });

      console.log("Posição 0 do array (Deve ser o mais recente):", stats.finished[0].protocol, stats.finished[0].createdAt);
    }

    if (stats.detailedLogs.length > 0) {
      console.log("%c--- RESUMO DE TRIAGEM ATIVA ---", "color: #fbbf24; font-weight: bold;");
      console.table(stats.departmentSummary);
      console.log("%c--- CHAMADOS EM TRIAGEM DETALHADOS ---", "color: #fbbf24; font-weight: bold;");
      console.table(stats.detailedLogs);
    }

    console.groupEnd();
  }, [departments, periods, stats.detailedLogs, stats.departmentSummary, stats.finished]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      <div className="bg-slate-900/50 border border-slate-700/50 rounded-xl p-5 flex flex-col xl:flex-row items-center justify-between shadow-xl gap-5">
        <div className="flex items-center gap-4">
          <div className="bg-sky-500/10 p-3 rounded-lg">
            <Activity className="w-6 h-6 text-sky-400" />
          </div>
