    try {
      let finalUrlStr = baseUrl.replace(/\/$/, '');
      if (!finalUrlStr.endsWith(path)) finalUrlStr += path;

      const url = new URL(finalUrlStr);
      const lib = url.protocol === 'https:' ? https : http;

      const jsonBody = JSON.stringify(body);

      const options = {
        method: 'GET',
        headers: { 
          'Authorization': token.startsWith('Bearer ') ? token : `Bearer ${token}`,
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(jsonBody)
        },
        hostname: url.hostname,
        port: url.port || (url.protocol === 'https:' ? 443 : 80),
        path: url.pathname,
        rejectUnauthorized: false,
        timeout: 60000 
      };

      const req = lib.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => {
          try { 
            const parsed = JSON.parse(data);
            if (res.statusCode >= 400) {
                resolve({ ok: false, error: parsed });
            } else {
                resolve({ ok: true, data: parsed });
            }
          } catch (e) {
            resolve({ ok: false, error: { message: `JSON parse error: ${e.message}`, statusCode: res.statusCode, rawData: data } });
          }
        });
      });

      req.on('error', (e) => {
        resolve({ ok: false, error: { message: `Request error: ${e.message}` } });
      });

      req.on('timeout', () => {
        req.destroy(new Error('Request timed out'));
        resolve({ ok: false, error: { message: 'Request timed out' } });
      });

      req.end(jsonBody);
    } catch (e) {
      console.error("Critical error in request", e);
      reject(e);
    }
